input.sparql:
SELECT ?sensor ?equipment ?label WHERE {
  ?sensor a brick:Electric_Power_Sensor .
  ?sensor brick:isPointOf ?equipment .
  ?equipment rdfs:label ?label .
}

SELECT DISTINCT ?type WHERE {
  ?s a brick:Electric_Power_Sensor .
  ?s brick:isPointOf ?t .
  ?t rdf:type ?type .
}

SELECT DISTINCT ?type WHERE {
  ?sensor a brick:Electric_Power_Sensor .
  ?sensor brick:isPointOf ?target .
  OPTIONAL { ?target rdfs:label ?label . }
  BIND(?label AS ?type)
}
ORDER BY ?type

SELECT ?sensor ?target ?label ?tsref WHERE {
  ?sensor a brick:Electric_Power_Sensor .
  ?sensor brick:isPointOf ?target .
  OPTIONAL { ?target rdfs:label ?label }
  ?sensor ref:hasExternalReference ?tsref .
}
